import { existsSync } from 'node:fs'
import { join } from 'node:path'
import { migrate } from 'drizzle-orm/postgres-js/migrator'
import type { Database } from './client'

/**
 * Folder with the SQL migrations generated by drizzle-kit. This file runs from
 * src/db/ in development and is bundled into dist/ for production, so look in
 * both places relative to it.
 */
export const MIGRATIONS_FOLDER =
  [
    join(import.meta.dirname, '..', '..', 'drizzle'),
    join(import.meta.dirname, '..', 'drizzle'),
  ].find((dir) => existsSync(join(dir, 'meta', '_journal.json'))) ??
  join(import.meta.dirname, '..', '..', 'drizzle')

export async function runMigrations(database: Database) {
  await migrate(database.db, { migrationsFolder: MIGRATIONS_FOLDER })
}
